"""Company narrative: purpose, method and renovation offering."""
def render(page, intro, kicker, link, pic, service_cards, finalcta):
 def navigation(active):
  return '<nav class="company-story-nav arc-container" aria-label="Η εταιρεία μας">'+''.join(f'<a href="{u}"'+(' aria-current="page"' if u==active else '')+f'>{t}</a>' for u,t in [('/el/etaireia','Ποιοι είμαστε'),('/el/filosofia','Φιλοσοφία & αξίες'),('/el/diadikasia','Η διαδικασία μας')])+'</nav>'
 why='Πιστεύουμε ότι ένας χώρος μπορεί να αλλάξει τον τρόπο που ζεις. Να σου δώσει περισσότερο φως, περισσότερη ελευθερία, περισσότερες δυνατότητες. Γι’ αυτό δημιουργούμε κατοικίες που ξεκινούν από τον άνθρωπο και δίνουν ουσιαστικό νόημα σε κάθε τετραγωνικό.'
 steps=[('Καταλαβαίνουμε πώς θέλεις να ζεις','Πριν σχεδιάσουμε τοίχους, καταλαβαίνουμε τις ανάγκες σου. Πώς ζεις σήμερα, τι σε περιορίζει και τι θέλεις να αλλάξει.'),('Δίνουμε μορφή στην ιδέα','Αποτυπώνουμε το διαμέρισμα, εξετάζουμε τις τεχνικές δυνατότητες και μελετάμε διαρρύθμιση, υλικά και φωτισμό. Οι κατόψεις και τα renders κάνουν τις επιλογές ορατές πριν ξεκινήσουν οι εργασίες.'),('Οργανώνουμε τη δημιουργία','Συμφωνούμε το αντικείμενο, τον προϋπολογισμό και το πλάνο εργασιών. Συντονίζουμε την υλοποίηση και συζητάμε τις αλλαγές μαζί σου, με καθαρή εικόνα για την επίδρασή τους στο έργο.'),('Παραδίδουμε και φροντίζουμε','Ελέγχουμε το αποτέλεσμα και καταγράφουμε όσα χρειάζονται ολοκλήρωση. Μετά την παράδοση, παραμένουμε σημείο επικοινωνίας για υποστήριξη, σύμφωνα με τους όρους του έργου.')]
 body='<main id="main" class="company-story">'+intro('Η ΕΤΑΙΡΕΙΑ ΜΑΣ / ΠΟΙΟΙ ΕΙΜΑΣΤΕ','Δημιουργούμε χώρους.<br><em>Ανοίγουμε δυνατότητες.</em>','Η Arcus Development αναλαμβάνει ολικές ανακαινίσεις διαμερισμάτων, από τη μελέτη και τον σχεδιασμό μέχρι την κατασκευή και την παράδοση.',link('#why','Το γιατί μας','arc-link'))+navigation('/el/etaireia')
 body+='<section class="company-purpose" id="why"><div class="arc-container arc-section">'+kicker('01 / WHY — ΓΙΑΤΙ ΔΗΜΙΟΥΡΓΟΥΜΕ')+'<h2>Σχεδιάζουμε χώρους<br><em>γύρω από τη ζωή σου.</em></h2><p class="company-manifesto">'+why+'</p><p>Μια νέα αρχή για το σπίτι σου. Μια νέα προοπτική για ένα ακίνητο που περιμένει να αξιοποιηθεί. Η ανακαίνιση αποκτά αξία όταν υπηρετεί αυτό που θέλεις να γίνει η επόμενη μέρα.</p></div></section>'
 body+='<figure class="company-real-project arc-container">'+pic('/assets/portfolio/soulioti-17/home-kitchen-light.webp','Ανακαινισμένη κουζίνα της Arcus Development με ξύλο, ανθρακί επιφάνειες και φυσικό φως')+'<figcaption>Από την ιδέα στον χώρο που ζεις — ολοκληρωμένο έργο Arcus Development.</figcaption></figure>'
 body+='<section class="arc-section arc-container" id="how"><div class="section-title"><div>'+kicker('02 / HOW — ΠΩΣ ΔΟΥΛΕΥΟΥΜΕ')+'<h2>Η φαντασία δίνει κατεύθυνση.<br><em>Η μελέτη δίνει μορφή.</em></h2></div><p>Συνδέουμε τη δημιουργικότητα με την τεχνική σκέψη και την οργανωμένη υλοποίηση. Κάθε απόφαση χρειάζεται να υπηρετεί την ίδια ιδέα.</p></div><div class="steps-grid">'+''.join(f'<article><span>{i+1:02d}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(steps))+'</div><div class="company-story-actions">'+link('/el/diadikasia','Δες τη διαδικασία μας','arc-link')+link('/el/filosofia','Οι αξίες μας στην πράξη','arc-link')+'</div></section>'
 body+='<section class="arc-section arc-container" id="what"><div class="section-title"><div>'+kicker('03 / WHAT — ΤΙ ΚΑΝΟΥΜΕ')+'<h2>Ολικές ανακαινίσεις.<br><em>Με τον δικό σου σκοπό.</em></h2></div><p>Εστιάζουμε στην ολική ανακαίνιση διαμερισμάτων: από την αποτύπωση και τη μελέτη μέχρι την κατασκευή και την παράδοση. Για το σπίτι που θέλεις να ζήσεις ή για την αξιοποίηση του ακινήτου σου.</p></div><div class="service-grid">'+service_cards+'</div></section>'
 body+='<section class="arc-section arc-container editorial-split-new"><div>'+kicker('ΜΕΛΟΣ ΤΟΥ ARCUS GROUP')+'<h2>Κοινές αξίες.<br>Η δική μας δημιουργική έκφραση.</h2></div><div><p>Μοιραζόμαστε με την Arcus την εμπιστοσύνη, την ακεραιότητα, την ποιότητα, τη συνεργασία και την καινοτομία. Στην Development, οι αξίες αυτές παίρνουν μορφή σε μια κάτοψη, σε μια τεχνική επιλογή, στη συνεννόηση και στη φροντίδα του έργου.</p><p>Μέσα από το δίκτυο του ομίλου, συνδέουμε την ανακαίνιση με τις ανάγκες πριν και μετά: αγορά, εκτίμηση, μίσθωση και διαχείριση.</p>'+link('/el/one-stop-shop','Γνώρισε το One Stop Shop','arc-link')+'</div></section>'+finalcta()+'</main>'
 page('etaireia','Ποιοι είμαστε — Γιατί, Πώς, Τι | Arcus Development','Γιατί δημιουργούμε, πώς δουλεύουμε και τι αναλαμβάνουμε. Η φιλοσοφία της Arcus Development στην ολική ανακαίνιση διαμερισμάτων.',body)
 values=[('Εμπιστοσύνη','Η δημιουργία χρειάζεται καθαρή συνεννόηση.','Συζητάμε το αντικείμενο και τις επιλογές με τρόπο κατανοητό. Εξηγούμε τι περιλαμβάνει η πρόταση και τι χρειάζεται ξεχωριστή συμφωνία.'),('Ακεραιότητα','Η σωστή απόφαση ξεκινά από την αλήθεια.','Ελέγχουμε τις δυνατότητες του ακινήτου πριν προτείνουμε παρεμβάσεις. Ο διαχωρισμός εξετάζεται με βάση τις τεχνικές και νομικές προϋποθέσεις κάθε έργου· η απόδοση μιας επένδυσης δεν προεξοφλείται.'),('Ποιότητα','Το αποτέλεσμα κρίνεται και στην καθημερινή χρήση.','Συνδέουμε την αισθητική με τη λειτουργικότητα, τα υλικά και τις λεπτομέρειες εφαρμογής. Δίνουμε προσοχή τόσο σε όσα φαίνονται όσο και στις υποδομές που στηρίζουν τον χώρο.'),('Συνεργασία','Η καλύτερη ιδέα εξελίσσεται μαζί.','Η γνώση σου για τον τρόπο που ζεις συναντά τη μελέτη και την εμπειρία των συνεργείων. Συντονίζουμε τις διαφορετικές ειδικότητες γύρω από έναν κοινό στόχο.'),('Καινοτομία','Κάθε περιορισμός είναι αφορμή για νέα σκέψη.','Εξερευνούμε εναλλακτικές διαρρυθμίσεις και αξιοποιούμε την τρισδιάστατη απεικόνιση για πιο ξεκάθαρες επιλογές. Επιλέγουμε λύσεις επειδή προσφέρουν ουσία στον χώρο.'),('Δημιουργικότητα','Ο χώρος σου χρειάζεται τη δική σου υπογραφή.','Σχεδιάζουμε με αφετηρία τις ανάγκες και τις επιθυμίες σου. Το φως, οι υφές και οι αναλογίες συνθέτουν ένα σύνολο με χαρακτήρα και σκοπό.')]
 body='<main id="main" class="company-story">'+intro('Η ΕΤΑΙΡΕΙΑ ΜΑΣ / ΦΙΛΟΣΟΦΙΑ & ΑΞΙΕΣ','Όσα πιστεύουμε.<br><em>Σε όσα δημιουργούμε.</em>','Οι κοινές αξίες της Arcus καθοδηγούν τον τρόπο που συνεργαζόμαστε. Η δημιουργικότητα είναι ο τρόπος που τις εκφράζουμε στον χώρο.')+navigation('/el/filosofia')
 body+='<section class="company-purpose"><div class="arc-container arc-section">'+kicker('ΤΟ ΓΙΑΤΙ ΜΑΣ')+'<h2>Πρώτα ο άνθρωπος.<br><em>Έπειτα η κάτοψη.</em></h2><p class="company-manifesto">'+why+'</p>'+link('/el/etaireia#how','Πώς γίνεται πράξη','arc-link')+'</div></section><section class="arc-section arc-container"><div class="section-title"><div>'+kicker('ΟΙ ΑΞΙΕΣ ΜΑΣ ΣΤΗΝ ΠΡΑΞΗ')+'<h2>Αρχές που καθοδηγούν<br>κάθε απόφαση.</h2></div></div><div class="company-values">'+''.join(f'<article><span class="arc-kicker">{i+1:02d} / {t}</span><h3>{h}</h3><p>{d}</p></article>' for i,(t,h,d) in enumerate(values))+'</div></section><section class="arc-section arc-container editorial-split-new"><div>'+kicker('ΑΠΟ ΤΟ ΓΙΑΤΙ ΣΤΟ ΑΠΟΤΕΛΕΣΜΑ')+'<h2>Η φιλοσοφία φαίνεται<br>στα έργα μας.</h2></div><div><p>Δες τις πραγματικές μεταμορφώσεις: την αρχική κατάσταση, τις σχεδιαστικές επιλογές και το αποτέλεσμα κάθε ανακαίνισης, με το διαθέσιμο υλικό του έργου.</p>'+link('/el/erga','Εξερεύνησε τα έργα μας','arc-link')+'</div></section>'+finalcta()+'</main>'
 page('filosofia','Φιλοσοφία & αξίες | Arcus Development','Οι κοινές αξίες της Arcus και η δημιουργική τους έκφραση στη μελέτη, τη συνεργασία και την ολική ανακαίνιση διαμερισμάτων.',body)
